<?php $d = json_decode(file_get_contents("routes_data.json"), true); $dupes = []; $uris = []; $unprotected = []; $closure = []; foreach($d as $r) { $uri = $r["uri"]; $methods = implode(",", $r["methods"]); $key = "$methods $uri"; if(isset($uris[$key])) $dupes[] = $key; $uris[$key] = true; if($r["action"] === "Closure") $closure[] = $r["uri"]; $mw = implode(",", (array)$r["middleware"]); if(!str_contains($mw, "auth") && !str_contains($mw, "api") && str_contains($uri, "admin")) $unprotected[] = $uri; } echo "Duplicates: ".count($dupes)."\nUnprotected Admin: ".count($unprotected)."\nClosure Routes: ".count($closure)."\n";
